#include <vector>
using namespace std;

class Solution {
public:
    int minPrefixRemoval(vector<int>& nums) {
        int i = (int)nums.size() - 1;
        while (i > 0 && nums[i - 1] < nums[i]) i--;
        return i;
    }
};

class Solution {
    public int minPrefixRemoval(int[] nums) {
        int i = nums.length - 1;
        while (i > 0 && nums[i - 1] < nums[i]) i--;
        return i;
    }
}

